<script setup>
import {ref,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {api} from '../api'
import Icon from '../components/Icon.vue'
const PdfViewer=defineAsyncComponent(()=>import('../components/PdfViewer.vue'))
const data=ref(null),cycle=ref(null),busy=ref(false),error=ref(''),pdf=ref('')
let disposed=false
function clearPdf(){if(pdf.value)URL.revokeObjectURL(pdf.value);pdf.value=''}
async function load(){busy.value=true;error.value='';clearPdf();try{const query=new URLSearchParams();if(cycle.value)query.set('cycle',cycle.value);const result=await api('/enrollment?'+query);if(disposed)return;data.value=result;cycle.value=result.cycle;if(result.groups.length){const blob=await api('/enrollment/pdf?'+new URLSearchParams({cycle:result.cycle}),{blob:true});if(!disposed)pdf.value=URL.createObjectURL(blob)}}catch(e){if(!disposed)error.value=Object.values(e.errors||{}).flat().join(' ')||e.message}finally{busy.value=false}}
onMounted(load)
onBeforeUnmount(()=>{disposed=true;clearPdf()})
</script>
<template><div class="page-heading"><div><span class="eyebrow">TU CAMINO ACADÉMICO</span><h1>Mi boleta de inscripción<span class="heading-dot">.</span></h1><p>Consulta tus asignaturas inscritas y guarda tu boleta en PDF.</p></div><v-btn v-if="pdf" :href="pdf" :download="'boleta-inscripcion-'+(data?.student.student_code||'ULS').replace(/[^A-Za-z0-9_-]/g,'_')+'.pdf'" color="primary" size="large"><Icon name="Download" :size="18" class="mr-2"/>Descargar boleta</v-btn></div><v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{error}} <button class="ml-2" @click="load">Reintentar</button></v-alert><section v-if="data" class="panel enrollment-summary"><div class="enrollment-student"><span class="stat-icon blue"><Icon name="GraduationCap" :size="25"/></span><div><h2>{{data.student.name}}</h2><p>{{data.student.student_code}} · {{data.student.career}}</p></div></div><v-select v-if="data.cycles.length" v-model="cycle" :items="data.cycles" label="Ciclo académico" hide-details :disabled="busy" class="enrollment-cycle" @update:model-value="load"/></section><v-progress-linear v-if="busy" indeterminate color="primary" class="mb-5"/><section v-if="pdf" class="panel enrollment-preview"><div class="panel-heading"><div><h2>Tu inscripción, en un solo documento</h2><p>Vista previa de tu boleta · Ciclo {{cycle}}</p></div><Icon name="FileText"/></div><PdfViewer :key="pdf" :url="pdf" label="Boleta de inscripción"/></section><div v-else-if="busy" class="panel empty-state enrollment-loading"><Icon name="FileText" :size="38"/><strong>Preparando tu boleta</strong><p>Estamos organizando tu información y tus asignaturas.</p></div><section v-else-if="data&&!data.groups.length" class="panel empty-state"><Icon name="BookOpen" :size="38"/><strong>Aún no tienes asignaturas inscritas</strong><p>Cuando la institución registre tus grupos, podrás consultar y descargar aquí tu boleta de inscripción.</p></section><p v-if="pdf" class="table-help"><Icon name="ShieldCheck" :size="15"/>Este documento contiene únicamente tu información y tus asignaturas inscritas.</p></template>
